let react = require("react");
//#region src/useObjectUrl/index.ts
const useObjectUrl = (object) => {
	const [url, setUrl] = (0, react.useState)();
	(0, react.useEffect)(() => {
		if (object) setUrl(URL.createObjectURL(object));
		return () => {
			if (url) URL.revokeObjectURL(url);
		};
	}, [object]);
	return url;
};
//#endregion
exports.useObjectUrl = useObjectUrl;
